import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Avatar, Badge, Flex, Typography } from 'antd';
import cn from 'classnames';

import CommentIcon from 'assets/images/icons/comment.svg?react';
import EyeIcon from 'assets/images/icons/eye.svg?react';
import SmileIcon from 'assets/images/icons/smile.svg?react';
import { ChannelAvatar } from 'entities/Channel';
import { TopPublishedPostsRead } from 'entities/Report';
import { formatDate, formatNumber } from 'shared/utils';

import styles from './ReportPost.module.scss';

interface IReportPostProps extends HTMLAttributes<HTMLDivElement> {
	postData: TopPublishedPostsRead;
}

export const ReportPost: FC<IReportPostProps> = ({ className, postData, ...props }) => {
	const { published_post: post } = postData;
	const { t } = useTranslation();
	const [expanded, setExpanded] = useState(false);

	return (
		<div {...props} className={cn(className, styles.post)}>
			<Flex gap={8} className={styles.info}>
				{!!post.images.length && (
					<Avatar
						shape="square"
						size={76}
						className={styles.image}
						icon={<img src={post.images[0].image} alt={post.channel.name} />}
					/>
				)}
				<Typography.Paragraph
					className={styles.lineClamp}
					ellipsis={{
						rows: 4,
						expandable: 'collapsible',
						expanded,
						onExpand: (_, info) => setExpanded(info.expanded),
					}}>
					{post.content}
				</Typography.Paragraph>
			</Flex>

			<Flex gap={4} justify={'space-between'} className={cn(styles.part, styles.schedule)}>
				{post?.published_at ? (
					<Badge status="success" text={t('Опубликовано')} />
				) : (
					<Badge status="processing" text={t('Опубликуется')} />
				)}
				<Typography.Text type="secondary" style={{ fontSize: 12 }}>
					{formatDate(new Date(post.published_at || ''), 'long')}
				</Typography.Text>
			</Flex>

			{post?.published_at && (
				<Flex gap={4} justify={'space-between'} className={cn(styles.part, styles.schedule)}>
					<Typography.Text type="secondary" style={{ fontSize: 12 }}>
						{t('Вовлеченность')}
					</Typography.Text>
					<Flex gap={12} align="center">
						<Flex gap={2} align="center">
							<Typography.Text type="secondary" style={{ lineHeight: 0 }}>
								<EyeIcon />
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12, lineHeight: '12px' }}>
								{formatNumber(post.views_count || 0)}
							</Typography.Text>
						</Flex>
						<Flex gap={2} align="center">
							<Typography.Text type="secondary" style={{ lineHeight: 0 }}>
								<SmileIcon />
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12, lineHeight: '12px' }}>
								{formatNumber(post.likes_count || 0)}
							</Typography.Text>
						</Flex>
						<Flex gap={2} align="center">
							<Typography.Text type="secondary" style={{ lineHeight: 0 }}>
								<CommentIcon />
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12, lineHeight: '12px' }}>
								{formatNumber(post.comments_count || 0)}
							</Typography.Text>
						</Flex>
					</Flex>
				</Flex>
			)}

			{post.channel && postData.approved_amount && (
				<Flex gap={4} className={styles.part}>
					<div className={styles.report}>
						<Flex vertical>
							<Typography.Text style={{ fontSize: 12 }} strong>
								+ {postData.approved_amount} {t('РУБ')}
							</Typography.Text>
							<Typography.Text style={{ fontSize: 10 }} type="secondary">
								{t('Принес вам этот пост')}
							</Typography.Text>
						</Flex>
					</div>

					<div className={styles.report}>
						<Flex gap={8}>
							<ChannelAvatar name={post.channel.name} logo={post.channel.logo_url} size={32} />
							<Flex vertical>
								<Typography.Text style={{ fontSize: 12 }} strong>
									{post.channel.name}
								</Typography.Text>
								<Typography.Text style={{ fontSize: 10 }} type="secondary">
									{formatNumber(post.channel.subscribers_count || 0)}
								</Typography.Text>
							</Flex>
						</Flex>
					</div>
				</Flex>
			)}
		</div>
	);
};
