import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, FlexProps, Typography } from 'antd';
import cn from 'classnames';

import ChartIcon from 'assets/images/icons/chart.svg?react';
import { ReportPost, StatisticsRead } from 'entities/Report';
import { EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import styles from './ReportPosts.module.scss';

interface IReportPostsProps extends FlexProps {
	stats?: StatisticsRead;
}

export const ReportPosts: FC<IReportPostsProps> = ({ className, stats, ...props }) => {
	const { t } = useTranslation();

	if (!stats) return null;

	return (
		<Flex {...props} vertical gap={12} className={cn(className, styles.posts)}>
			<Typography.Text type="secondary">{t('Топ-3 самых высокооплачиваемых постов за период:')}</Typography.Text>

			<Flex {...props} vertical gap={8}>
				{stats.top_published_posts.map((post) => {
					return <ReportPost postData={post} key={post.published_post.uuid} />;
				})}
			</Flex>

			<Button
				onClick={() => sendYmEvent('click_request_statistics', { page_screen: EYmPageScreen.STATISTICS_SCREEN })}
				variant="outlined"
				color="primary"
				size="large"
				icon={<ChartIcon />}
				iconPosition="end">
				{t('Запросить полную статистику')}
			</Button>
		</Flex>
	);
};
