import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex } from 'antd';

import statsImage from 'assets/images/titles/reports.webp';
import { useChannelsListQuery } from 'entities/Channel';
import { EarningsChart, ReportPosts, ReportSummary, useStatisticsRetrieveQuery } from 'entities/Report';
import { CHANNELS_LIMIT, EFilters, getUrlParamsForApi, ReportsMainFilters, useFilters } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { useBackButton } from 'shared/hooks';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { ButtonStyleLink, Content, NoResults, OverlayLoader, Page, PageTitle } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

interface IReportsProps extends HTMLAttributes<HTMLDivElement> {}

export const Reports: FC<IReportsProps> = ({ ...props }) => {
	const { t } = useTranslation();
	useBackButton(`${EMainRoutes.DASHBOARD}`);

	const [searchParams] = useSearchParams();
	const { data: stats, isFetching: isFetchingStats } = useStatisticsRetrieveQuery(getUrlParamsForApi(searchParams));
	const { data: channelList, isFetching: isChannelFetching } = useChannelsListQuery({
		[EPaginationParams.LIMIT]: CHANNELS_LIMIT,
	});

	const noData =
		!Number(stats?.metrics.current_period.approved_actions_count) &&
		!Number(stats?.metrics.prev_period.approved_actions_count) &&
		!Number(stats?.metrics.current_period.avg_income_per_post) &&
		!Number(stats?.metrics.prev_period.avg_income_per_post) &&
		!Number(stats?.metrics.current_period.avg_income_per_action) &&
		!Number(stats?.metrics.prev_period.avg_income_per_action) &&
		!stats?.top_offers.length &&
		!stats?.top_published_posts.length;

	const { getFiltersCount } = useFilters();

	const hasChannels = !!channelList?.results.length;
	const hasFilters = getFiltersCount([EFilters.CHANNEL, EFilters.DATE_AFTER, EFilters.DATE_BEFORE]) > 0;

	return (
		<Page {...props}>
			<PageTitle
				subtitle={t('Следите за эффективностью ваших постов в каналах')}
				image={<img src={statsImage} width={72} height={72} alt={t('Статистика')} />}>
				{t('Статистика')}
			</PageTitle>
			<Content>
				{(isFetchingStats || isChannelFetching) && <OverlayLoader />}

				<Flex vertical gap={24}>
					<ReportsMainFilters />
					{noData && !isFetchingStats && (
						<NoResults
							subtext={
								!hasChannels
									? t(
											'К сожалению, пока тут ничего. Для размещения постов, пожалуйста, добавьте свой первый канал или группу',
										)
									: hasFilters
										? t('Нет результатов для этого поискового запроса')
										: t('К сожалению, пока тут ничего. Размещайте посты и получайте выплаты')
							}
							goTo={
								<ButtonStyleLink
									size="large"
									to={hasChannels ? `/${EMainRoutes.CATALOG}` : `/${EMainRoutes.CHANNELS}/${EMainRoutes.CREATE}`}
									onClick={() =>
										sendYmEvent(hasChannels ? 'click_catalog' : 'click_add_channel', {
											page_screen: EYmPageScreen.STATISTICS_SCREEN,
										})
									}
									block
									color="primary"
									variant="outlined">
									{hasChannels ? t('В каталог') : t('Добавить')}
								</ButtonStyleLink>
							}
						/>
					)}
					{!noData && <ReportSummary stats={stats} />}
					{!noData && <EarningsChart />}
					{!noData && <ReportPosts stats={stats} />}
				</Flex>
			</Content>
		</Page>
	);
};

export default Reports;
