import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Radio } from 'antd';

import { useFilters } from 'features/Filters';
import { EFilters } from 'features/Filters/model/enums';

interface IReportsEarningsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsEarningsFilters: FC<IReportsEarningsFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue, onFilterChange } = useFilters();

	return (
		<Flex {...props} vertical gap={12}>
			<Radio.Group
				value={getFilterValue(EFilters.EARNINGS_TYPE) || 'payments'}
				onChange={(e) => onFilterChange(EFilters.EARNINGS_TYPE, e.target.value)}
				block>
				<Radio.Button value="payments">
					{t('Оплаты')}, {t('РУБ')}
				</Radio.Button>
				<Radio.Button value="actions">{t('Платные действия')}</Radio.Button>
			</Radio.Group>

			<Radio.Group
				value={getFilterValue(EFilters.AGGREGATE_BY) || 'week'}
				onChange={(e) => onFilterChange(EFilters.AGGREGATE_BY, e.target.value)}
				block>
				<Radio.Button value="day">{t('День')}</Radio.Button>
				<Radio.Button value="month">{t('Месяц')}</Radio.Button>
				<Radio.Button value="year">{t('Год')}</Radio.Button>
			</Radio.Group>
		</Flex>
	);
};
